pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint256 settleBlocks) public {
        // settleBlocks is how many blocks to advance before settling
        settleBlocks = bound(settleBlocks, 1, 256);
        address actor = address(0x1234);
        vm.deal(actor, 2 ether);
        // fund contract
        vm.deal(address(c), 1 ether);
        // lockInGuess
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);
        uint256 recordedBlock = c.guesses(actor).block;
        // advance blocks
        vm.roll(block.number + settleBlocks);
        // settle
        vm.prank(actor);
        c.settle();
        uint256 recordedBlockAfter = c.guesses(actor).block;
        // After settle, recorded block is reset to 0.
        // The invariant: if settle was called after the recorded block, it resets to 0 regardless of outcome.
        // But a stronger invariant: the recorded block before settle must equal block.number at lockInGuess time + 1.
        // We can check: the recorded block (before settle) must be > block.number at lockInGuess time.
        // Since we saved recordedBlock before advancing, we can assert it was set correctly.
        assertTrue(recordedBlock == block.number - settleBlocks + 1);
    }
}

