pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C{value: 1 ether}();
    }

    function testFuzz_property(bytes32 hash, uint8 blockDelay) public {
        // blockDelay > 0 so settle possible after lock
        vm.assume(blockDelay > 0 && blockDelay <= 250);
        address actor = address(0x1000);
        vm.deal(actor, 2 ether);

        uint256 balanceBefore = actor.balance;

        vm.startPrank(actor);
        c.lockInGuess{value: 1 ether}(hash);
        vm.stopPrank();

        // advance blocks so settle() becomes possible
        vm.roll(block.number + blockDelay);

        vm.startPrank(actor);
        c.settle();
        vm.stopPrank();

        uint256 balanceAfter = actor.balance;

        // Reference contract: if guess matches blockhash, actor gets 2 ether back -> net +1 ether.
        // Buggy contract: guess stored as zero, never matches a non-zero blockhash, so actor gets no transfer
        // and ends up with -1 ether overall.
        // The test asserts that balance increased by exactly 1 ether from lock-in payment + 2 ether payout.
        // This holds for ALL inputs on correct contract (when answer matches), and FAILS on buggy one (where answer never matches).
        // Note: if blockhash(answerBlock) is zero (block beyond 256), both versions don't pay out, so we restrict delay ≤ 250.
        assertTrue(balanceAfter == balanceBefore + 1 ether);
    }
}

