pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint48 blockDelta) public {
        // 1. Keep parameters in admissible domain
        vm.assume(blockDelta > 1 && blockDelta < 256);

        // 2. Fund a user and have them lock in a guess
        address guesser = address(0x1);
        vm.deal(guesser, 1 ether);
        vm.prank(guesser);
        c.lockInGuess{value: 1 ether}(hash);

        // Advance blocks past the guess block
        vm.roll(block.number + uint256(blockDelta));

        // Record contract balance before settle
        uint256 balanceBefore = address(c).balance;

        // Call settle, catch potential revert
        bool ok = true;
        vm.prank(guesser);
        try c.settle() { ok = true; } catch { ok = false; }

        if (ok) {
            uint256 payout = balanceBefore - address(c).balance;
            assertTrue(payout <= 2 ether);
        }
    }
}
